#!/bin/bash
# pantheon-host-broker-rehearsal-script/v1 (T-2920 U4a). GENERATED by tools/host_broker_rehearsal.py --emit-commands; do not edit.
# run id 0123456789ab; machine pantheon-rehearsal-0123456789ab; repo /home/orchestrator/pantheon-config at commit 1111111111111111111111111111111111111111.
# FIXTURE: rehearsal inputs only; never a real operator-batch value.
# Run as root by orchestrator:  bash THIS prerequisites | run | rollback-prerequisites
# Every step is one fixed argv under timeout; a failure exits non-zero and the EXIT trap tears down.
# In-machine actuation is ONLY via the U4b entrypoint tools/host_broker_rehearsal_live.py (attested; refuses elsewhere).
# KNOWN FIRST-RUN RISK: U4b's mountinfo allowlist refuses a rw /sys/fs/bpf or /sys/fs/pstore (the 7 real
# nspawn 255 mounts are accepted per Recovery D15 W3, T-5703). If systemd mounts one inside the machine, every
# U4b call refuses (rc 3); P0 captures /proc/self/mountinfo BEFORE any in-machine U4b call, so that refusal
# is diagnosable from the evidence.
# After a PARTIAL prerequisites failure, run rollback-prerequisites before re-running prerequisites.
set -euo pipefail
umask 077
export LC_ALL=C
export PATH=/usr/sbin:/usr/bin:/sbin:/bin

# ======================================================================
# PREREQUISITES: orchestrator runs these ONCE (root, network). The harness never executes them.
#   PRE-a: host packages; systemd-container pinned to the installed systemd version; the simulated new-package list is recorded first and a simulated upgrade or removal refuses
#     command:  apt-get install -y --no-install-recommends --no-remove systemd-container=$SYSTEMD_VERSION debootstrap
#     ROLLBACK: xargs -r -a /var/lib/pantheon-rehearsal/prereq-purge-set.txt apt-get purge -y   (purges only the Purg/Remv set of apt-get -s purge over /var/lib/pantheon-rehearsal/prereq-new-packages.txt; a name in that set NOT on the recorded list refuses (never a cascade); a smaller or empty set (a partial or failed install) proceeds; window: apt state could change between the purge simulation and the purge; it needs root, lasts seconds, and the rollback runs once under orchestrator's supervision)
#   PRE-b: one-time debootstrap of the noble minbase tree (network: http://archive.ubuntu.com/ubuntu)
#     command:  debootstrap --variant=minbase --components=main,universe --include=systemd,systemd-sysv,dbus,python3,python3-venv,python3-dbus,python3-gi,python3-yaml,acl,sudo,passwd,procps noble /var/cache/pantheon-rehearsal/base-noble http://archive.ubuntu.com/ubuntu
#     ROLLBACK: rm -rf --one-file-system /var/cache/pantheon-rehearsal/base-noble   (always (cache only))
#   PRE-c: one-time hash-pinned wheelhouse download of the commit's requirements.lock (network: PyPI)
#     command:  python3 -m pip download --require-hashes --only-binary=:all: --no-deps --no-cache-dir -r /var/cache/pantheon-rehearsal/requirements.lock -d /var/cache/pantheon-rehearsal/wheelhouse
#     ROLLBACK: rm -rf --one-file-system /var/cache/pantheon-rehearsal/wheelhouse   (always (cache only))
# ======================================================================
prerequisites() {
  test "$(id -u)" = 0
  install -d -m 0755 /var/lib/pantheon-rehearsal
  test ! -e /var/lib/pantheon-rehearsal/prereq-prestate.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-simulation.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-new-packages.txt
  if dpkg-query -W -f='${Status}\n' systemd-container 2>/dev/null | grep -qx 'install ok installed'; then echo 'systemd-container present'; else echo 'systemd-container absent'; fi >> /var/lib/pantheon-rehearsal/prereq-prestate.txt
  if dpkg-query -W -f='${Status}\n' debootstrap 2>/dev/null | grep -qx 'install ok installed'; then echo 'debootstrap present'; else echo 'debootstrap absent'; fi >> /var/lib/pantheon-rehearsal/prereq-prestate.txt
  SYSTEMD_VERSION="$(dpkg-query -W -f='${Version}' systemd)"
  printf '%s\n' "$SYSTEMD_VERSION" | grep -qxE '[0-9A-Za-z.+~:-]+'
  echo "systemd-version $SYSTEMD_VERSION" >> /var/lib/pantheon-rehearsal/prereq-prestate.txt
  timeout 120 apt-get -s install --no-install-recommends "systemd-container=$SYSTEMD_VERSION" debootstrap > /var/lib/pantheon-rehearsal/prereq-simulation.txt
  if grep -qE '^(Inst [^ ]+ \[|Remv )' /var/lib/pantheon-rehearsal/prereq-simulation.txt; then echo 'PRE-a would upgrade or remove an installed package; refusing' >&2; exit 3; fi
  grep '^Inst ' /var/lib/pantheon-rehearsal/prereq-simulation.txt | cut -d' ' -f2 > /var/lib/pantheon-rehearsal/prereq-new-packages.txt || true
  timeout 900 apt-get install -y --no-install-recommends --no-remove "systemd-container=$SYSTEMD_VERSION" debootstrap  # PRE-a
  install -d -m 0755 /var/cache/pantheon-rehearsal
  test -e /var/cache/pantheon-rehearsal/base-noble || timeout 1800 debootstrap --variant=minbase --components=main,universe --include=systemd,systemd-sysv,dbus,python3,python3-venv,python3-dbus,python3-gi,python3-yaml,acl,sudo,passwd,procps noble /var/cache/pantheon-rehearsal/base-noble http://archive.ubuntu.com/ubuntu  # PRE-b
  timeout 120 git -C /home/orchestrator/pantheon-config -c safe.directory=/home/orchestrator/pantheon-config show 1111111111111111111111111111111111111111:tools/host_mcp_adapter/dist/requirements.lock > /var/cache/pantheon-rehearsal/requirements.lock
  test -e /var/cache/pantheon-rehearsal/wheelhouse || timeout 1800 python3 -m pip download --require-hashes --only-binary=:all: --no-deps --no-cache-dir -r /var/cache/pantheon-rehearsal/requirements.lock -d /var/cache/pantheon-rehearsal/wheelhouse  # PRE-c
}

rollback_prerequisites() {
  test "$(id -u)" = 0
  test -f /var/lib/pantheon-rehearsal/prereq-prestate.txt
  timeout 300 rm -rf --one-file-system /var/cache/pantheon-rehearsal/wheelhouse  # ROLLBACK PRE-c
  timeout 300 rm -rf --one-file-system /var/cache/pantheon-rehearsal/base-noble  # ROLLBACK PRE-b
  rm -f /var/cache/pantheon-rehearsal/requirements.lock
  # ROLLBACK PRE-a (begin): simulate the purge, refuse a removal not on the recorded list, purge the rest
  # window: apt state could change between the purge simulation and the purge; it needs root, lasts seconds, and the rollback runs once under orchestrator's supervision
  # simulate over the recorded names dpkg knows; the subset check below stays against the FULL list
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then timeout 60 xargs -a /var/lib/pantheon-rehearsal/prereq-new-packages.txt dpkg-query -W '-f=${Package}\n' > /var/lib/pantheon-rehearsal/prereq-purge-known.txt || test $? = 123; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then : > /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt && test -s /var/lib/pantheon-rehearsal/prereq-purge-known.txt; then timeout 120 xargs -r -a /var/lib/pantheon-rehearsal/prereq-purge-known.txt apt-get -s purge > /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then grep -E '^(Purg|Remv) ' /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt | cut -d' ' -f2 | sort -u > /var/lib/pantheon-rehearsal/prereq-purge-set.txt || true; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then sort -u /var/lib/pantheon-rehearsal/prereq-new-packages.txt > /var/lib/pantheon-rehearsal/prereq-new-packages.sorted.txt; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then timeout 60 comm -23 /var/lib/pantheon-rehearsal/prereq-purge-set.txt /var/lib/pantheon-rehearsal/prereq-new-packages.sorted.txt > /var/lib/pantheon-rehearsal/prereq-purge-extra.txt; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt && test -s /var/lib/pantheon-rehearsal/prereq-purge-extra.txt; then timeout 60 xargs -a /var/lib/pantheon-rehearsal/prereq-purge-extra.txt echo 'PRE-a rollback would remove packages not in the recorded list:' >&2; exit 3; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt && test -s /var/lib/pantheon-rehearsal/prereq-purge-set.txt; then timeout 900 xargs -r -a /var/lib/pantheon-rehearsal/prereq-purge-set.txt apt-get purge -y; fi
  # verify BEFORE archiving: no recorded package may still be present (anything but not-installed); dpkg is the sentinel
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then timeout 60 xargs -a /var/lib/pantheon-rehearsal/prereq-new-packages.txt dpkg-query -W '-f=${Package} ${db:Status-Status}\n' dpkg > /var/lib/pantheon-rehearsal/prereq-verify-status.txt || test $? = 123; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt && ! grep -qx 'dpkg installed' /var/lib/pantheon-rehearsal/prereq-verify-status.txt; then echo 'PRE-a rollback verify: dpkg-query could not read the dpkg database; refusing' >&2; exit 3; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then grep -v '^dpkg ' /var/lib/pantheon-rehearsal/prereq-verify-status.txt | grep -v ' not-installed$' | cut -d' ' -f1 > /var/lib/pantheon-rehearsal/prereq-verify-left.txt || true; fi
  if test -s /var/lib/pantheon-rehearsal/prereq-new-packages.txt && test -s /var/lib/pantheon-rehearsal/prereq-verify-left.txt; then timeout 60 xargs -a /var/lib/pantheon-rehearsal/prereq-verify-left.txt echo 'PRE-a rollback incomplete: still installed:' >&2; exit 3; fi
  # ROLLBACK PRE-a (end)
  # archive (never delete) the record of what was installed and rolled back; prerequisites can re-run
  PREREQ_TS="$(date -u +%Y%m%dT%H%M%SZ)"
  printf '%s\n' "$PREREQ_TS" | grep -qxE '[0-9]{8}T[0-9]{6}Z'
  install -d -m 0755 /var/lib/pantheon-rehearsal/prereq-archive
  test ! -e "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS"
  install -d -m 0755 "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS"
  if test -e /var/lib/pantheon-rehearsal/prereq-prestate.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-prestate.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-simulation.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-simulation.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-new-packages.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-new-packages.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-purge-set.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-purge-set.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-new-packages.sorted.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-new-packages.sorted.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-purge-extra.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-purge-extra.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-purge-known.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-purge-known.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-verify-status.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-verify-status.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  if test -e /var/lib/pantheon-rehearsal/prereq-verify-left.txt; then timeout 60 mv -n -- /var/lib/pantheon-rehearsal/prereq-verify-left.txt "/var/lib/pantheon-rehearsal/prereq-archive/$PREREQ_TS/"; fi
  test ! -e /var/lib/pantheon-rehearsal/prereq-prestate.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-simulation.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-new-packages.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-purge-simulation.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-purge-set.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-new-packages.sorted.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-purge-extra.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-purge-known.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-verify-status.txt
  test ! -e /var/lib/pantheon-rehearsal/prereq-verify-left.txt
}

teardown() {
  set +e
  timeout 60 machinectl poweroff pantheon-rehearsal-0123456789ab
  timeout 180 systemctl stop pantheon-rehearsal-0123456789ab.service
  timeout 300 machinectl remove pantheon-rehearsal-0123456789ab || echo 'LEFTOVER MACHINE: machinectl remove pantheon-rehearsal-0123456789ab failed' >&2
  test ! -e /var/lib/machines/pantheon-rehearsal-0123456789ab || { echo 'LEFTOVER MACHINE: /var/lib/machines/pantheon-rehearsal-0123456789ab still exists; remove it by hand with machinectl remove pantheon-rehearsal-0123456789ab' >&2; }
  timeout 300 rm -rf --one-file-system /srv/rehearsal/repo
  rmdir /srv/rehearsal
  rm -f /var/lib/pantheon-rehearsal/0123456789ab/nonce
  rm -f /var/lib/pantheon-rehearsal/0123456789ab/repo.tar
  rm -f /var/lib/pantheon-rehearsal/0123456789ab/fixture-token
}

run() {
  # --- R0 preflight, staging and the FORBIDDEN-ON-HOST canary
  test "$(id -u)" = 0
  test -x /usr/bin/systemd-nspawn
  test -x /usr/bin/machinectl
  test -x /usr/bin/systemd-run
  test -x /usr/bin/setpriv
  test -d /var/cache/pantheon-rehearsal/base-noble
  test -d /var/cache/pantheon-rehearsal/wheelhouse
  test ! -e /etc/pantheon-rehearsal
  test ! -e /srv/rehearsal
  test ! -e /var/lib/machines/pantheon-rehearsal-0123456789ab
  test ! -e /var/lib/pantheon-rehearsal/0123456789ab
  install -d -m 0755 /var/lib/pantheon-rehearsal /var/lib/pantheon-rehearsal/0123456789ab /var/lib/pantheon-rehearsal/0123456789ab/evidence /srv/rehearsal /srv/rehearsal/repo
  trap teardown EXIT
  head -c 32 /dev/urandom > /var/lib/pantheon-rehearsal/0123456789ab/nonce
  NONCE_SHA256="$(sha256sum /var/lib/pantheon-rehearsal/0123456789ab/nonce | cut -d' ' -f1)"
  HOST_MACHINE_ID_SHA256="$(sha256sum /etc/machine-id | cut -d' ' -f1)"
  echo 'euid 0' > /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-prestate.txt
  if dpkg-query -W -f='${Status}\n' systemd-container 2>/dev/null | grep -qx 'install ok installed'; then echo 'systemd-container present'; else echo 'systemd-container absent'; fi >> /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-prestate.txt
  if dpkg-query -W -f='${Status}\n' debootstrap 2>/dev/null | grep -qx 'install ok installed'; then echo 'debootstrap present'; else echo 'debootstrap absent'; fi >> /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-prestate.txt
  echo 'attestation-dir absent' >> /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-prestate.txt
  printf '{"compensate_enabled":false,"evidence_class":"rehearsal:nspawn:fixture-inputs","fixture":true,"host_machine_id_sha256":"%s","live":false,"machine":"pantheon-rehearsal-0123456789ab","nonce_sha256":"%s","repo_commit":"1111111111111111111111111111111111111111","run_id":"0123456789ab","schema":"pantheon-host-broker-rehearsal-run/v1"}\n' "$HOST_MACHINE_ID_SHA256" "$NONCE_SHA256" > /var/lib/pantheon-rehearsal/0123456789ab/evidence/run.json
  timeout 300 git -C /home/orchestrator/pantheon-config -c safe.directory=/home/orchestrator/pantheon-config archive --format=tar --output=/var/lib/pantheon-rehearsal/0123456789ab/repo.tar 1111111111111111111111111111111111111111
  timeout 300 tar -x -f /var/lib/pantheon-rehearsal/0123456789ab/repo.tar -C /srv/rehearsal/repo
  timeout 120 git -C /home/orchestrator/pantheon-config -c safe.directory=/home/orchestrator/pantheon-config ls-tree -r -z --name-only 1111111111111111111111111111111111111111 > /var/lib/pantheon-rehearsal/0123456789ab/tracked-files
  test -f /srv/rehearsal/repo/tools/host_broker_rehearsal_live.py || { echo 'the U4b entrypoint tools/host_broker_rehearsal_live.py is absent from the staged commit; refusing' >&2; exit 3; }
  install -d -o nobody -g nogroup -m 0700 /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging
  timeout 300 /usr/bin/setpriv --reuid=nobody --regid=nogroup --clear-groups --no-new-privs -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal.py --fixture-inputs /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out --repo /srv/rehearsal/repo
  chmod 0644 /var/lib/pantheon-rehearsal/0123456789ab/tracked-files
  timeout 600 /usr/bin/setpriv --reuid=nobody --regid=nogroup --clear-groups --no-new-privs -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_install.py plan --manifest /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out/manifest.json --registry /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out/registry.json --tracked-files /var/lib/pantheon-rehearsal/0123456789ab/tracked-files --out /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/host-plan.json
  timeout 60 chown -R root:root /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging
  if timeout 60 find /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging ! -type f ! -type d -print -quit | grep -q .; then echo 'inputs-staging holds a symlink or a non-regular entry; refusing' >&2; exit 3; fi
  install -m 0644 /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/host-plan.json /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-plan.json
  # host-untouched: ONLY the installer's own targets, derived from the plan; bounded in entries, bytes and time
  timeout 300 /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal.py --host-manifest /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-before.json --plan /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-plan.json
  # FORBIDDEN-ON-HOST CANARY (Recovery D15 addition 2): guard-probe on the HOST must refuse with rc 3; it is observe-only
  rc=0
  timeout 60 /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal_live.py guard-probe --nonce-sha256 "$NONCE_SHA256" --plan /var/lib/pantheon-rehearsal-inputs/work/plan.json --manifest /var/lib/pantheon-rehearsal-inputs/manifest.json --registry /var/lib/pantheon-rehearsal-inputs/registry.json --tracked-files /var/lib/pantheon-rehearsal-inputs/tracked-files --inputs /var/lib/pantheon-rehearsal-inputs/inputs.json --receipt /var/lib/pantheon-install-receipts/guard-probe.json > /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-canary.json || rc=$?
  printf '%s\n' "$rc" > /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-canary.rc
  test "$rc" = 3
  # --- R1 image: per-run copy of the cached base; copy (never bind) inputs and wheelhouse in
  install -d -m 0700 /var/lib/machines
  timeout 900 cp -a --reflink=auto /var/cache/pantheon-rehearsal/base-noble /var/lib/machines/pantheon-rehearsal-0123456789ab
  install -d -m 0755 /var/lib/machines/pantheon-rehearsal-0123456789ab/srv/rehearsal/repo /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs
  install -d -m 0700 /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs/wheelhouse /var/lib/machines/pantheon-rehearsal-0123456789ab/etc/pantheon-rehearsal
  install -d -o 65534 -g 65534 -m 0700 /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs/work
  install -m 0644 /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out/FIXTURE.json /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs/FIXTURE.json
  install -m 0644 /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out/approver-policy.json /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs/approver-policy.json
  install -m 0644 /var/lib/pantheon-rehearsal/0123456789ab/inputs-staging/out/guard-manifest.json /var/lib/machines/pantheon-rehearsal-0123456789ab/var/lib/pantheon-rehearsal-inputs/guard-manifest.json
