  sleep 35
  timeout 60 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/setpriv --reuid=pantheon-hostmonitor --regid=pantheon-hostmonitor --clear-groups --no-new-privs -- /usr/bin/busctl --system get-property org.pantheon.HostBroker1 /org/pantheon/HostBroker1/Health org.pantheon.Health1 Status > /var/lib/pantheon-rehearsal/0123456789ab/evidence/health-ready.txt
  rc=0
  timeout 60 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/busctl --system call org.freedesktop.DBus /org/freedesktop/DBus org.freedesktop.DBus StartServiceByName su org.pantheon.HostExecutor1.U2001 0 > /var/lib/pantheon-rehearsal/0123456789ab/evidence/start-service.txt || rc=$?
  printf '%s\n' "$rc" > /var/lib/pantheon-rehearsal/0123456789ab/evidence/start-service.rc
  timeout 60 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/busctl --system call org.freedesktop.DBus /org/freedesktop/DBus org.freedesktop.DBus GetConnectionUnixUser s org.pantheon.HostExecutor1.U2001 > /var/lib/pantheon-rehearsal/0123456789ab/evidence/executor-owner.txt || true
  timeout 600 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/srv/rehearsal/repo -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal_live.py verify --nonce-sha256 "$NONCE_SHA256" --plan /var/lib/pantheon-rehearsal-inputs/work/plan.json --manifest /var/lib/pantheon-rehearsal-inputs/manifest.json --registry /var/lib/pantheon-rehearsal-inputs/registry.json --tracked-files /var/lib/pantheon-rehearsal-inputs/tracked-files --inputs /var/lib/pantheon-rehearsal-inputs/inputs.json --receipt /var/lib/pantheon-install-receipts/main.json > /var/lib/pantheon-rehearsal/0123456789ab/evidence/verify.out
  # --- P12: identical rerun (CF-8) and the token scans (CF-10)
  timeout 300 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal.py --tree-manifest - --root /etc/dbus-1/system.d --root /etc/group --root /etc/pantheon --root /etc/passwd --root /etc/shadow --root /etc/systemd/system --root /run/pantheon-host-install --root /srv/rehearsal-canary --root /usr/local/lib/pantheon --root /usr/local/libexec --root /usr/share/dbus-1/system-services --root /var/lib/pantheon > /var/lib/pantheon-rehearsal/0123456789ab/evidence/rerun-S0.json
  timeout 1800 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/srv/rehearsal/repo -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal_live.py apply --nonce-sha256 "$NONCE_SHA256" --plan /var/lib/pantheon-rehearsal-inputs/work/plan.json --manifest /var/lib/pantheon-rehearsal-inputs/manifest.json --registry /var/lib/pantheon-rehearsal-inputs/registry.json --tracked-files /var/lib/pantheon-rehearsal-inputs/tracked-files --inputs /var/lib/pantheon-rehearsal-inputs/inputs.json --receipt /var/lib/pantheon-install-receipts/rerun.json --execute > /var/lib/pantheon-rehearsal/0123456789ab/evidence/rerun.out
  timeout 60 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/cat /var/lib/pantheon-install-receipts/rerun.json > /var/lib/pantheon-rehearsal/0123456789ab/evidence/rerun-receipt.json
  timeout 300 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal.py --tree-manifest - --root /etc/dbus-1/system.d --root /etc/group --root /etc/pantheon --root /etc/passwd --root /etc/shadow --root /etc/systemd/system --root /run/pantheon-host-install --root /srv/rehearsal-canary --root /usr/local/lib/pantheon --root /usr/local/libexec --root /usr/share/dbus-1/system-services --root /var/lib/pantheon > /var/lib/pantheon-rehearsal/0123456789ab/evidence/rerun-S1.json
  timeout 120 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/journalctl --no-pager -o cat > /var/lib/pantheon-rehearsal/0123456789ab/evidence/journal-all.txt
  rc=0
  timeout 300 /usr/bin/systemd-run --machine=pantheon-rehearsal-0123456789ab --pipe --wait --quiet --working-directory=/ -- /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/grep -rcaF --exclude=bot-token -f /var/lib/pantheon-rehearsal-inputs/bot-token /etc/dbus-1/system.d /etc/pantheon /etc/systemd/system /usr/local/libexec /var/lib/pantheon-host-approval /var/lib/pantheon-host-broker /var/lib/pantheon-install-receipts > /var/lib/pantheon-rehearsal/0123456789ab/evidence/token-scan-machine.txt || rc=$?
  printf '%s\n' "$rc" > /var/lib/pantheon-rehearsal/0123456789ab/evidence/token-scan-machine.rc
  test "$rc" = 1
  rc=0
  timeout 300 grep -rlaF -f /var/lib/pantheon-rehearsal/0123456789ab/fixture-token /var/lib/pantheon-rehearsal/0123456789ab/evidence > /var/lib/pantheon-rehearsal/0123456789ab/evidence/token-scan-host.txt || rc=$?
  printf '%s\n' "$rc" > /var/lib/pantheon-rehearsal/0123456789ab/evidence/token-scan-host.rc
  test "$rc" = 1
  # --- R9 host-after manifest (teardown runs on EXIT)
  timeout 300 /usr/bin/env -i LC_ALL=C PATH=/usr/bin:/bin /usr/bin/python3 -I /srv/rehearsal/repo/tools/host_broker_rehearsal.py --host-manifest /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-after.json --plan /var/lib/pantheon-rehearsal/0123456789ab/evidence/host-plan.json
  echo 'rehearsal run 0123456789ab finished; check: python3 -I tools/host_broker_rehearsal.py --check-evidence /var/lib/pantheon-rehearsal/0123456789ab/evidence'
}

case "${1:-}" in
  prerequisites) prerequisites ;;
  run) run ;;
  rollback-prerequisites) rollback_prerequisites ;;
  *) echo 'usage: THIS prerequisites | run | rollback-prerequisites' >&2; exit 64 ;;
esac
